23	
24	  it("toggles mute and captions with accessible state", () => {
25	    renderWithProviders(
26	      <CallStage name="Maya" avatarColor="#5B8C7E" endLabel="End call" onEnd={vi.fn()} />,
27	    );
28	    const mute = screen.getByRole("button", { name: "Mute" });
29	    fireEvent.click(mute);
30	    expect(
31	      screen.getByRole("button", { name: "Unmute" }),
