36	  });
37	
38	  it("calls onEnd with the elapsed seconds when ended", () => {
39	    vi.useFakeTimers();
40	    const onEnd = vi.fn().mockResolvedValue(undefined);
41	    renderWithProviders(
42	      <CallStage name="Maya" avatarColor="#5B8C7E" endLabel="End call" onEnd={onEnd} />,
43	    );
44	    act(() => {
45	      vi.advanceTimersByTime(3000);
46	    });
47	    fireEvent.click(screen.getByRole("button", { name: "End call" }));
48	    expect(onEnd).toHaveBeenCalledWith(3);
49	  });
50	
51	  it("has no a11y violations", async () => {
52	    const { container } = renderWithProviders(
53	      <CallStage name="Maya" avatarColor="#5B8C7E" endLabel="End call" onEnd={vi.fn()} />,
54	    );
55	    expect(await axe(container)).toHaveNoViolations();
